reference_solution:
def trap(height):
    l, r = 0, len(height) - 1
    lm = rm = water = 0
    while l < r:
        if height[l] < height[r]:
            lm = max(lm, height[l])
            water += lm - height[l]
            l += 1
        else:
            rm = max(rm, height[r])
            water += rm - height[r]
            r -= 1
    return water

brute_force_solution:
def trap(height):
    total = 0
    for i, h in enumerate(height):
        total += min(max(height[:i + 1]), max(height[i:])) - h
    return total

